function qrMemberFromUrl(){try{const v=new URL(location.href).searchParams.get('member')||'';return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(v)?v.toLowerCase():'';}catch{return '';}}
function clearQrMemberUrl(){try{const u=new URL(location.href);u.searchParams.delete('member');u.searchParams.delete('source');history.replaceState({},'',u.pathname+u.search+u.hash);}catch{}}
