 if(presets.length){const chips=container.querySelector('.product-quick .quick-chips');for(const p of presets)chips.append(button(`${p.name} · ${money(p.price)}`,()=>{const blank=entries.find(e=>!e.name.value.trim()&&Number(e.price.value||0)===0);if(blank){blank.name.value=p.name;blank.qty.value=1;blank.price.value=p.price;}else add({name:p.name,qty:1,price:p.price});container.dispatchEvent(new Event('input',{bubbles:true}));},'small secondary'));}
